class Solution {
    public int reverse(int x) {
        long sign = x < 0 ? -1 : 1;
        String digits = new StringBuilder(String.valueOf(Math.abs((long) x))).reverse().toString();
        long val = sign * Long.parseLong(digits);
        return (val < Integer.MIN_VALUE || val > Integer.MAX_VALUE) ? 0 : (int) val;
    }
}

