using System;

public class Solution {
    public int Reverse(int x) {
        long sign = x < 0 ? -1 : 1;
        char[] arr = Math.Abs((long)x).ToString().ToCharArray();
        Array.Reverse(arr);
        long val = sign * long.Parse(new string(arr));
        return (val < int.MinValue || val > int.MaxValue) ? 0 : (int)val;
    }
}

